#!/usr/bin/env bash
set -euo pipefail

# Authorise the Jenkins deploy key (generated by local/up.ps1, mounted read-only).
install -d -o ubuntu -g ubuntu -m 700 /home/ubuntu/.ssh
cp /run/secrets/app_deploy_key.pub /home/ubuntu/.ssh/authorized_keys
chown ubuntu:ubuntu /home/ubuntu/.ssh/authorized_keys
chmod 600 /home/ubuntu/.ssh/authorized_keys

# Same layout as the EC2 app host. /opt/app/state is a named volume shared read-only
# with platform-api, which shows release state in the UI.
install -d -o ubuntu -g ubuntu /opt/app
chown ubuntu:ubuntu /opt/app/state
printf 'APP_PORT=%s\n' "${APP_PORT:-80}" > /opt/app/host.env
chown ubuntu:ubuntu /opt/app/host.env

# Let ubuntu use the Docker socket, whatever group owns it (root on Docker Desktop).
gid="$(stat -c '%g' /var/run/docker.sock)"
group="$(getent group "$gid" | cut -d: -f1 || true)"
if [[ -z "$group" ]]; then
  groupadd -g "$gid" dockerhost
  group=dockerhost
fi
usermod -aG "$group" ubuntu

ssh-keygen -A >/dev/null
exec /usr/sbin/sshd -D -e
